class MarketingSemanticClient {
 public static function schema():array {
  $str=['type'=>'string'];$int=['type'=>'integer'];$strings=['type'=>'array','items'=>$str];$box=['type'=>'array','items'=>['type'=>'number'],'minItems'=>4,'maxItems'=>4];$obj=fn($p)=>['type'=>'object','additionalProperties'=>false,'properties'=>$p,'required'=>array_keys($p)];
  $observation=$obj(['sample_id'=>$str,'bbox'=>$box,'confidence'=>['type'=>'string','enum'=>['high','uncertain']],'visible'=>['type'=>'boolean'],'identity_match'=>['type'=>'boolean'],'people'=>['type'=>'array','items'=>$box]]);
  $target=$obj(['target_id'=>['type'=>'string','enum'=>['product']],'label'=>$str,'reference_ids'=>$strings,'fact_ids'=>$strings,'mode'=>['type'=>'string','enum'=>['static','moving']],'kind'=>['type'=>'string','enum'=>['circle','arrow']],'start_frame'=>$int,'end_frame'=>$int,'observations'=>['type'=>'array','items'=>$observation]]);$target['type']=['object','null'];
