  $scene=$obj(['scene_number'=>$int,'fact_ids'=>$strings,'reason'=>$str,'card'=>$card,'target'=>$target,'layout_observations'=>['type'=>'array','items'=>$layout],'confidence'=>['type'=>'string','enum'=>['high','uncertain']],'skip_reason'=>$str]);
  return $obj(['summary'=>$str,'scenes'=>['type'=>'array','items'=>$scene]]);
 }
 public function inspect(array $e):array {
