  abort_unless(($result['status']??'')==='completed',422,'语义分析未完整返回；没有自动重试。');$text='';foreach($result['output']??[] as $o)foreach($o['content']??[] as $part)if(($part['type']??'')==='output_text')$text.=$part['text']??'';
  return ['answer'=>json_decode($text,true,64,JSON_THROW_ON_ERROR),'usage'=>$result['usage']??[],'model'=>$result['model']??MarketingOptimizationClient::MODEL,'response_id'=>$result['id']??null];
 }
}
